function verifiedImageMime(filePath) { const bytes=fs.readFileSync(filePath).subarray(0,16); if(bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'image/jpeg'; if(bytes.length >= 8 && bytes.subarray(0,8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))) return 'image/png'; if(bytes.length >= 12 && bytes.subarray(0,4).toString('ascii') === 'RIFF' && bytes.subarray(8,12).toString('ascii') === 'WEBP') return 'image/webp'; return null; }
function imageDimensions(filePath,mime) { try { const bytes=fs.readFileSync(filePath);if(mime==='image/png'&&bytes.length>=24)return{width:bytes.readUInt32BE(16),height:bytes.readUInt32BE(20)};if(mime==='image/jpeg'){let offset=2;while(offset+9<bytes.length){if(bytes[offset]!==0xff){offset++;continue;}const marker=bytes[offset+1],length=bytes.readUInt16BE(offset+2);if([0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf].includes(marker))return{width:bytes.readUInt16BE(offset+7),height:bytes.readUInt16BE(offset+5)};if(length<2)break;offset+=2+length;}}if(mime==='image/webp'&&bytes.length>=30){const type=bytes.subarray(12,16).toString('ascii');if(type==='VP8X')return{width:1+bytes.readUIntLE(24,3),height:1+bytes.readUIntLE(27,3)};if(type==='VP8 '&&bytes.length>=30)return{width:bytes.readUInt16LE(26)&0x3fff,height:bytes.readUInt16LE(28)&0x3fff};if(type==='VP8L'&&bytes.length>=25){const bits=bytes.readUInt32LE(21);return{width:1+(bits&0x3fff),height:1+((bits>>14)&0x3fff)};}} } catch(_error){} return{width:null,height:null}; }
function safeFile(root, storedName) { const file=path.join(root,path.basename(String(storedName || ''))); return file.startsWith(root) ? file : null; }
function cleanupUploaded(req) { if(!req.file) return; const file=safeFile(assetDir,req.file.filename); if(file && fs.existsSync(file)) fs.unlinkSync(file); }
function cleanupMasterUploaded(req) { if(!req.file) return; const file=safeFile(masterArtworkDir,req.file.filename); if(file && fs.existsSync(file)) fs.unlinkSync(file); }
async function setting(key, queryable=db) { const [[row]]=await queryable.query('SELECT SettingValue FROM BBS_Settings WHERE SettingKey=? LIMIT 1',[key]); return String(row?.SettingValue || '0'); }
