function masterArtworkPayload(row) { return { id:Number(row.id),templateKind:row.TemplateKind,side:row.Side,versionNo:Number(row.VersionNo),originalName:row.OriginalName,mimeType:row.MimeType,fileSize:Number(row.FileSize||0),pixelWidth:row.PixelWidth==null?null:Number(row.PixelWidth),pixelHeight:row.PixelHeight==null?null:Number(row.PixelHeight),status:row.Status,createdAt:row.CreatedAt,activatedAt:row.ActivatedAt,archivedAt:row.ArchivedAt }; }
function scopedArtworkPayload(row) { return { slotId:Number(row.ArtworkSlotID||row.id),slotKey:row.SlotKey,artworkRole:row.ArtworkRole,templateKind:row.TemplateKind||null,departmentId:row.DepartmentID==null?null:Number(row.DepartmentID),departmentName:row.DepartmentName||null,safetyUnitId:row.SafetyUnitID==null?null:Number(row.SafetyUnitID),safetyUnitName:row.SafetyUnitName||null,isActive:Boolean(row.IsActive),rowVersion:Number(row.RowVersion||1),versionId:row.ArtworkVersionID==null?null:Number(row.ArtworkVersionID),versionNo:row.VersionNo==null?null:Number(row.VersionNo),originalName:row.OriginalName||null,mimeType:row.MimeType||null,fileSize:row.FileSize==null?null:Number(row.FileSize),pixelWidth:row.PixelWidth==null?null:Number(row.PixelWidth),pixelHeight:row.PixelHeight==null?null:Number(row.PixelHeight),status:row.Status||null,createdAt:row.CreatedAt||null,activatedAt:row.ActivatedAt||null,archivedAt:row.ArchivedAt||null }; }
function assetPayload(row) { return { id:Number(row.id), assetKey:row.AssetKey, masterArtworkId:row.MasterArtworkID==null?null:Number(row.MasterArtworkID), masterArtworkKind:row.MasterArtworkKind||null, masterArtworkSide:row.MasterArtworkSide||null, artworkVersionId:row.ArtworkVersionID==null?null:Number(row.ArtworkVersionID),artworkRole:row.ArtworkRole||null,artworkSlotKey:row.ArtworkSlotKey||null,originalName:row.OriginalName, mimeType:row.MimeType, fileSize:Number(row.FileSize || 0), pixelWidth:row.PixelWidth == null ? null : Number(row.PixelWidth), pixelHeight:row.PixelHeight == null ? null : Number(row.PixelHeight), status:row.Status }; }
function presetPayload(row) { return { id:Number(row.id),templateKind:String(row.TemplateKind),presetName:String(row.PresetName),status:String(row.Status),rowVersion:Number(row.RowVersion),createdAt:row.CreatedAt,updatedAt:row.UpdatedAt,trashedAt:row.TrashedAt||null }; }
function reusablePresetLayout(layout) {
    if(layout.elements.some(element=>element.assetId!=null||element.elementType==='StaticImage')) throw new DesignerValidationError('Remove static private images before saving this layout as a Preset. Card Artwork backgrounds are kept by the destination Draft.','PRIVATE_ASSET_PRESET_FORBIDDEN');
    return {templateKind:layout.templateKind,widthMM:layout.widthMM,heightMM:layout.heightMM,dpi:layout.dpi,duplexFlip:layout.duplexFlip,backRotation:layout.backRotation,sides:layout.sides.map(side=>({side:side.side,backgroundFit:side.backgroundFit,backgroundPositionXBP:side.backgroundPositionXBP,backgroundPositionYBP:side.backgroundPositionYBP,bleedMM:side.bleedMM,safeMarginMM:side.safeMarginMM})),elements:layout.elements.map(element=>({...element,assetId:null}))};
}
function applyPresetLayout(current,preset) {
    const sideByName=new Map(preset.sides.map(side=>[side.side,side]));
    return {...current,widthMM:preset.widthMM,heightMM:preset.heightMM,dpi:preset.dpi,duplexFlip:preset.duplexFlip,backRotation:preset.backRotation,sides:current.sides.map(side=>({...side,...sideByName.get(side.side),storageClass:side.storageClass,backgroundAssetId:side.backgroundAssetId,masterArtworkId:side.masterArtworkId,masterArtworkKind:side.masterArtworkKind,masterArtworkSide:side.masterArtworkSide,artworkVersionId:side.artworkVersionId,artworkRole:side.artworkRole,artworkSlotKey:side.artworkSlotKey,backgroundStoredName:side.backgroundStoredName,backgroundOriginalName:side.backgroundOriginalName,backgroundMimeType:side.backgroundMimeType,backgroundFileSize:side.backgroundFileSize,pixelWidth:side.pixelWidth,pixelHeight:side.pixelHeight})),elements:preset.elements.map(element=>({...element,assetId:null}))};
}
function rowLayout(version,sides,elements,assets=[]) {
    const assetByName=new Map(assets.map(row => [String(row.StoredName),row]));
    const layout={ templateKind:version.TemplateKind, widthMM:Number(version.WidthMM), heightMM:Number(version.HeightMM), dpi:Number(version.DPI), duplexFlip:version.DuplexFlip, backRotation:Number(version.BackRotation), sides:sides.map(row => {const asset=assetByName.get(String(row.BackgroundStoredName));return { side:row.Side,storageClass:row.StorageClass,backgroundAssetId:row.StorageClass==='DesignerAsset'&&asset?Number(asset.id):null,masterArtworkId:asset?.MasterArtworkID==null?null:Number(asset.MasterArtworkID),masterArtworkKind:asset?.MasterArtworkKind||null,masterArtworkSide:asset?.MasterArtworkSide||null,artworkVersionId:asset?.ArtworkVersionID==null?null:Number(asset.ArtworkVersionID),artworkRole:row.ArtworkRole||asset?.ArtworkRole||null,artworkSlotKey:asset?.ArtworkSlotKey||null,backgroundStoredName:row.StorageClass==='DesignerAsset'?'asset-reference':'parent-reference',backgroundOriginalName:row.BackgroundOriginalName,backgroundMimeType:row.BackgroundMimeType,backgroundFileSize:Number(row.BackgroundFileSize),pixelWidth:row.PixelWidth == null ? null : Number(row.PixelWidth),pixelHeight:row.PixelHeight == null ? null : Number(row.PixelHeight),backgroundFit:row.BackgroundFit,backgroundPositionXBP:Number(row.BackgroundPositionXBP),backgroundPositionYBP:Number(row.BackgroundPositionYBP),bleedMM:Number(row.BleedMM),safeMarginMM:Number(row.SafeMarginMM) };}), elements:elements.map(row => ({ elementKey:row.ElementKey,side:row.Side,elementType:row.ElementType,dataSourceKey:row.DataSourceKey,staticText:row.StaticText,assetId:row.AssetID == null ? null : Number(row.AssetID),xBP:Number(row.XBP),yBP:Number(row.YBP),widthBP:Number(row.WidthBP),heightBP:Number(row.HeightBP),rotationDeg:Number(row.RotationDeg),zIndex:Number(row.ZIndex),visible:Boolean(row.Visible),locked:Boolean(row.Locked),required:Boolean(row.Required),style:JSON.parse(row.StyleJSON || '{}') })) };
    return { ...version,id:Number(version.id),VersionNo:Number(version.VersionNo),RowVersion:Number(version.RowVersion),layout,assets:assets.map(assetPayload),readiness:assessLayout(layout) };
}
async function detail(id,queryable=db,lock=false,includeDeleted=false) { const [[version]]=await queryable.query(`SELECT * FROM BBS_Card_Layout_Versions WHERE id=?${includeDeleted?'':' AND IsDeleted=0'}${lock ? ' FOR UPDATE' : ''}`,[id]); if(!version) return null; const [sides]=await queryable.query("SELECT * FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back')",[id]); const [elements]=await queryable.query("SELECT * FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=? ORDER BY FIELD(Side,'Front','Back'),ZIndex,id",[id]); const [assets]=await queryable.query("SELECT a.*,m.TemplateKind MasterArtworkKind,m.Side MasterArtworkSide,s.ArtworkRole,s.SlotKey ArtworkSlotKey FROM BBS_Card_Layout_Assets a LEFT JOIN BBS_Card_Master_Artwork m ON m.id=a.MasterArtworkID LEFT JOIN BBS_Card_Artwork_Versions av ON av.id=a.ArtworkVersionID LEFT JOIN BBS_Card_Artwork_Slots s ON s.id=av.ArtworkSlotID WHERE a.LayoutVersionID=? AND a.Status='Active' ORDER BY a.CreatedAt,a.id",[id]); const record=rowLayout(version,sides,elements,assets);if(record.layout.sides.some(side=>side.storageClass==='CardArtwork')){const info=kindInfo(version.TemplateKind),[[parent]]=await queryable.query(`SELECT DepartmentID,SafetyUnitID FROM ${info.parentTable} WHERE id=?`,[version[info.parentColumn]]);if(parent?.DepartmentID){const resolved=await resolveActiveArtwork(queryable,{kind:info.kind,departmentId:parent.DepartmentID,safetyUnitId:parent.SafetyUnitID});for(const side of record.layout.sides){if(side.storageClass!=='CardArtwork')continue;const artwork=side.side==='Front'?resolved.front:resolved.back;Object.assign(side,{artworkVersionId:artwork?Number(artwork.ArtworkVersionID):null,artworkSlotKey:artwork?.SlotKey||null,backgroundOriginalName:artwork?.OriginalName||side.backgroundOriginalName,backgroundMimeType:artwork?.MimeType||side.backgroundMimeType,backgroundFileSize:artwork?Number(artwork.FileSize):0,pixelWidth:artwork?.PixelWidth==null?null:Number(artwork.PixelWidth),pixelHeight:artwork?.PixelHeight==null?null:Number(artwork.PixelHeight)});}}}return record; }
async function canonicalizeResources(connection,version,layout) {
    const info=kindInfo(version.TemplateKind),parentId=Number(version[info.parentColumn]); const [[parent]]=await connection.query(`SELECT * FROM ${info.parentTable} WHERE id=?`,[parentId]); if(!parent) throw new DesignerValidationError('Parent template was not found.');
    const [assets]=await connection.query("SELECT a.*,s.ArtworkRole,s.TemplateKind ArtworkKind,s.DepartmentID ArtworkDepartmentID,s.SafetyUnitID ArtworkSafetyUnitID,s.SlotKey ArtworkSlotKey FROM BBS_Card_Layout_Assets a LEFT JOIN BBS_Card_Artwork_Versions av ON av.id=a.ArtworkVersionID LEFT JOIN BBS_Card_Artwork_Slots s ON s.id=av.ArtworkSlotID WHERE a.LayoutVersionID=? AND a.Status='Active'",[version.id]); const assetsById=new Map(assets.map(row => [Number(row.id),row]));
    for(const id of new Set(layout.elements.map(item => item.assetId).filter(Boolean))) if(!assetsById.has(Number(id))) throw new DesignerValidationError('One or more static assets do not belong to this Draft.');
    layout.sides=layout.sides.map(side => {const expectedRole=side.side==='Front'?ARTWORK_ROLES.SCOPED_FRONT:ARTWORK_ROLES.GLOBAL_BACK;if(side.storageClass==='CardArtwork'&&side.artworkRole===expectedRole)return{...side,storageClass:'CardArtwork',backgroundAssetId:null,masterArtworkId:null,masterArtworkKind:null,masterArtworkSide:null,artworkVersionId:null,artworkSlotKey:null,backgroundStoredName:`logical:${expectedRole}`,backgroundOriginalName:expectedRole,backgroundMimeType:'application/x-bbs-card-artwork',backgroundFileSize:0,pixelWidth:null,pixelHeight:null};throw new DesignerValidationError(`${side.side} background must use logical ${expectedRole} Card Artwork.`,'CARD_ARTWORK_REQUIRED');});
    return layout;
}
async function validateElementAssets(connection,versionId,layout) {
    const [assets]=await connection.query("SELECT id FROM BBS_Card_Layout_Assets WHERE LayoutVersionID=? AND Status='Active'",[versionId]);
    const owned=new Set(assets.map(row=>Number(row.id)));
    for(const id of new Set(layout.elements.map(item=>item.assetId).filter(Boolean))) if(!owned.has(Number(id))) throw new DesignerValidationError('One or more static assets do not belong to this Draft.');
}
async function insertContent(connection,versionId,layout) { for(const side of layout.sides) await connection.query('INSERT INTO BBS_Card_Layout_Sides(LayoutVersionID,Side,StorageClass,ArtworkRole,BackgroundStoredName,BackgroundOriginalName,BackgroundMimeType,BackgroundFileSize,PixelWidth,PixelHeight,BackgroundFit,BackgroundPositionXBP,BackgroundPositionYBP,BleedMM,SafeMarginMM) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[versionId,side.side,side.storageClass,side.artworkRole||null,side.backgroundStoredName,side.backgroundOriginalName,side.backgroundMimeType,side.backgroundFileSize,side.pixelWidth,side.pixelHeight,side.backgroundFit,side.backgroundPositionXBP,side.backgroundPositionYBP,side.bleedMM,side.safeMarginMM]); for(const element of layout.elements) await connection.query('INSERT INTO BBS_Card_Layout_Elements(LayoutVersionID,ElementKey,Side,ElementType,DataSourceKey,StaticText,AssetID,XBP,YBP,WidthBP,HeightBP,RotationDeg,ZIndex,Visible,Locked,Required,StyleJSON) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[versionId,element.elementKey,element.side,element.elementType,element.dataSourceKey,element.staticText,element.assetId,element.xBP,element.yBP,element.widthBP,element.heightBP,element.rotationDeg,element.zIndex,element.visible,element.locked,element.required,JSON.stringify(element.style)]); }

async function masterArtworkSnapshot(connection,versionId,kind,layout,_actor,_createdFiles) {
    const info=kindInfo(kind);const[[parent]]=await connection.query(`SELECT p.id,p.DepartmentID,p.SafetyUnitID FROM BBS_Card_Layout_Versions v JOIN ${info.parentTable} p ON p.id=v.${info.parentColumn} WHERE v.id=? AND p.IsDeleted=0`,[versionId]);
    if(!parent) throw new DesignerValidationError('A Designer Draft cannot be created for a template in Trash.','PARENT_TEMPLATE_TRASHED');
    if(!positiveInt(parent.DepartmentID))throw new DesignerValidationError(`${kind} template must select a Department before resolving Scoped Front Artwork.`,'CARD_ARTWORK_REQUIRED');
    const resolved=await resolveActiveArtwork(connection,{kind,departmentId:parent.DepartmentID,safetyUnitId:parent.SafetyUnitID},{lock:true});
    if(resolved.missing.length)throw new DesignerValidationError(`${resolved.missing.join(' and ')} Card Artwork is required for ${kind}, Department ${parent.DepartmentID}${parent.SafetyUnitID?`, Unit ${parent.SafetyUnitID}`:''}.`,'CARD_ARTWORK_REQUIRED');
    const bySide=new Map([['Front',resolved.front],['Back',resolved.back]]);
    for(const side of layout.sides){const artwork=bySide.get(side.side),source=safeFile(masterArtworkDir,artwork.StoredName),role=side.side==='Front'?ARTWORK_ROLES.SCOPED_FRONT:ARTWORK_ROLES.GLOBAL_BACK;if(!source||!fs.existsSync(source)||verifiedImageMime(source)!==artwork.MimeType)throw new DesignerValidationError(`${side.side} Card Artwork file is unavailable.`,'CARD_ARTWORK_REQUIRED');Object.assign(side,{storageClass:'CardArtwork',backgroundAssetId:null,masterArtworkId:null,masterArtworkKind:null,masterArtworkSide:null,artworkVersionId:Number(artwork.ArtworkVersionID),artworkRole:role,artworkSlotKey:artwork.SlotKey,backgroundStoredName:`logical:${role}`,backgroundOriginalName:artwork.OriginalName,backgroundMimeType:'application/x-bbs-card-artwork',backgroundFileSize:0,pixelWidth:artwork.PixelWidth==null?null:Number(artwork.PixelWidth),pixelHeight:artwork.PixelHeight==null?null:Number(artwork.PixelHeight)});}
    await connection.query('UPDATE BBS_Card_Layout_Versions SET PreviewDepartmentID=?,PreviewSafetyUnitID=? WHERE id=?',[parent.DepartmentID,parent.SafetyUnitID||null,versionId]);
    return layout;
}

router.get('/admin/card-artwork',isAdmin,async(_req,res)=>{try{const[rows]=await db.query("SELECT s.id ArtworkSlotID,s.SlotKey,s.ArtworkRole,s.TemplateKind,s.DepartmentID,d.Name DepartmentName,s.SafetyUnitID,u.name SafetyUnitName,s.IsActive,s.RowVersion,v.id ArtworkVersionID,v.VersionNo,v.OriginalName,v.MimeType,v.FileSize,v.PixelWidth,v.PixelHeight,v.Status,v.CreatedAt,v.ActivatedAt,v.ArchivedAt FROM BBS_Card_Artwork_Slots s LEFT JOIN master_departments d ON d.id=s.DepartmentID LEFT JOIN master_safetyunits u ON u.id=s.SafetyUnitID LEFT JOIN BBS_Card_Artwork_Versions v ON v.ArtworkSlotID=s.id ORDER BY FIELD(s.ArtworkRole,'GlobalBack','ScopedFront'),FIELD(s.TemplateKind,'Personal','Department'),d.Name,u.name,v.VersionNo DESC,v.id DESC");const records=rows.map(scopedArtworkPayload),active=records.filter(row=>row.isActive&&row.status==='Active');return res.json({success:true,data:{globalBack:active.find(row=>row.artworkRole===ARTWORK_ROLES.GLOBAL_BACK)||null,scopedFronts:active.filter(row=>row.artworkRole===ARTWORK_ROLES.SCOPED_FRONT),records}});}catch(error){return errorResponse(res,error,'scoped artwork catalog');}});
router.post('/admin/card-artwork/:role',isAdmin,(req,res)=>{masterArtworkUpload.single('artwork')(req,res,async uploadError=>{if(uploadError)return res.status(400).json({success:false,message:uploadError.code==='LIMIT_FILE_SIZE'?'Card Artwork must not exceed 10 MB.':'Card Artwork upload failed.'});if(!await requireEnabled(res)){cleanupMasterUploaded(req);return;}const connection=await db.getConnection();try{if(!req.file)throw new DesignerValidationError('A JPG, PNG, or WebP Card Artwork file is required.');const actualMime=verifiedImageMime(req.file.path);if(!actualMime||actualMime!==req.file.mimetype)throw new DesignerValidationError('Card Artwork content does not match its file type.');const dimensions=imageDimensions(req.file.path,actualMime),role=String(req.params.role||'').trim().toLowerCase();let artworkRole,kind=null,departmentId=null,safetyUnitId=null,slotKey;if(role==='global-back'){artworkRole=ARTWORK_ROLES.GLOBAL_BACK;slotKey=globalBackSlotKey();}else if(role==='scoped-front'){artworkRole=ARTWORK_ROLES.SCOPED_FRONT;kind=normalizeKind(req.body?.templateKind);({departmentId,safetyUnitId}=await validateUnitDepartment(connection,req.body?.departmentId,req.body?.safetyUnitId));slotKey=scopedFrontSlotKey(kind,departmentId,safetyUnitId);}else throw new DesignerValidationError('Artwork role must be global-back or scoped-front.');await connection.beginTransaction();let[[slot]]=await connection.query('SELECT * FROM BBS_Card_Artwork_Slots WHERE SlotKey=? FOR UPDATE',[slotKey]);if(!slot){const[result]=await connection.query('INSERT INTO BBS_Card_Artwork_Slots(SlotKey,ArtworkRole,TemplateKind,DepartmentID,SafetyUnitID,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?)',[slotKey,artworkRole,kind,departmentId,safetyUnitId,actorId(req),actorId(req)]);[[slot]]=await connection.query('SELECT * FROM BBS_Card_Artwork_Slots WHERE id=? FOR UPDATE',[result.insertId]);}const[[next]]=await connection.query('SELECT COALESCE(MAX(VersionNo),0)+1 nextNo FROM BBS_Card_Artwork_Versions WHERE ArtworkSlotID=?',[slot.id]);await connection.query("UPDATE BBS_Card_Artwork_Versions SET Status='Archived',ArchivedAt=NOW() WHERE ArtworkSlotID=? AND Status='Active'",[slot.id]);const[result]=await connection.query("INSERT INTO BBS_Card_Artwork_Versions(ArtworkSlotID,VersionNo,StoredName,OriginalName,MimeType,FileSize,PixelWidth,PixelHeight,Status,CreatedBy,ActivatedAt) VALUES(?,?,?,?,?,?,?,?, 'Active',?,NOW())",[slot.id,Number(next.nextNo),path.basename(req.file.filename),String(req.file.originalname||'artwork').slice(0,255),actualMime,req.file.size,dimensions.width,dimensions.height,actorId(req)]);await connection.query('UPDATE BBS_Card_Artwork_Slots SET IsActive=1,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[actorId(req),slot.id]);await connection.commit();const[[row]]=await db.query("SELECT s.id ArtworkSlotID,s.SlotKey,s.ArtworkRole,s.TemplateKind,s.DepartmentID,d.Name DepartmentName,s.SafetyUnitID,u.name SafetyUnitName,s.IsActive,s.RowVersion,v.id ArtworkVersionID,v.VersionNo,v.OriginalName,v.MimeType,v.FileSize,v.PixelWidth,v.PixelHeight,v.Status,v.CreatedAt,v.ActivatedAt,v.ArchivedAt FROM BBS_Card_Artwork_Slots s JOIN BBS_Card_Artwork_Versions v ON v.ArtworkSlotID=s.id LEFT JOIN master_departments d ON d.id=s.DepartmentID LEFT JOIN master_safetyunits u ON u.id=s.SafetyUnitID WHERE v.id=?",[result.insertId]);await logAudit(req,{action:'BBS_CARD_ARTWORK_ACTIVATE',module:'bbs',targetType:'BBS_Card_Artwork_Version',targetId:result.insertId,detail:`Activated ${slotKey} Artwork V${Number(next.nextNo)}.`,metadata:{slotKey,artworkRole,templateKind:kind,departmentId,safetyUnitId,versionNo:Number(next.nextNo)}});return res.status(201).json({success:true,data:scopedArtworkPayload(row)});}catch(error){await connection.rollback().catch(()=>{});cleanupMasterUploaded(req);return errorResponse(res,error,'scoped artwork upload');}finally{connection.release();}});});
router.get('/admin/card-artwork/versions/:id/file',isAdmin,async(req,res)=>{try{const id=positiveInt(req.params.id);const[[row]]=await db.query('SELECT * FROM BBS_Card_Artwork_Versions WHERE id=?',[id]);if(!row)return res.status(404).json({success:false,message:'Card Artwork version was not found.'});const file=safeFile(masterArtworkDir,row.StoredName);if(!file||!fs.existsSync(file)||verifiedImageMime(file)!==row.MimeType)return res.status(404).json({success:false,message:'Card Artwork file is unavailable.'});res.setHeader('Content-Type',row.MimeType);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(row.OriginalName)}`);res.setHeader('Cache-Control','private, no-store');return res.sendFile(file);}catch(error){return errorResponse(res,error,'scoped artwork file');}});

router.get('/admin/card-master-artwork',isAdmin,async(_req,res)=>{try{const[rows]=await db.query("SELECT * FROM BBS_Card_Master_Artwork ORDER BY FIELD(TemplateKind,'Personal','Department'),FIELD(Side,'Front','Back'),VersionNo DESC,id DESC");const records=rows.map(masterArtworkPayload),slots={Personal:{Front:null,Back:null},Department:{Front:null,Back:null}};for(const row of records)if(row.status==='Active')slots[row.templateKind][row.side]=row;return res.json({success:true,data:{slots,records}});}catch(error){return errorResponse(res,error,'master artwork catalog');}});
router.post('/admin/card-master-artwork/:kind/:side',isAdmin,(req,res)=>{masterArtworkUpload.single('artwork')(req,res,async uploadError=>{if(uploadError)return res.status(400).json({success:false,message:uploadError.code==='LIMIT_FILE_SIZE'?'Master Artwork must not exceed 10 MB.':'Master Artwork upload failed.'});if(!await requireEnabled(res)){cleanupMasterUploaded(req);return;}const connection=await db.getConnection();try{const kind=normalizeKind(req.params.kind),side=String(req.params.side||'').toLowerCase()==='back'?'Back':String(req.params.side||'').toLowerCase()==='front'?'Front':null;if(!side||!req.file)throw new DesignerValidationError('Template kind, side and a JPG, PNG, or WebP artwork file are required.');const actualMime=verifiedImageMime(req.file.path);if(!actualMime||actualMime!==req.file.mimetype)throw new DesignerValidationError('Master Artwork content does not match its file type.');const dimensions=imageDimensions(req.file.path,actualMime);await connection.beginTransaction();const[active]=await connection.query("SELECT id FROM BBS_Card_Master_Artwork WHERE TemplateKind=? AND Side=? AND Status='Active' FOR UPDATE",[kind,side]);const[[next]]=await connection.query('SELECT COALESCE(MAX(VersionNo),0)+1 nextNo FROM BBS_Card_Master_Artwork WHERE TemplateKind=? AND Side=?',[kind,side]);if(active.length)await connection.query("UPDATE BBS_Card_Master_Artwork SET Status='Archived',ArchivedAt=NOW() WHERE TemplateKind=? AND Side=? AND Status='Active'",[kind,side]);const[result]=await connection.query("INSERT INTO BBS_Card_Master_Artwork(TemplateKind,Side,VersionNo,StoredName,OriginalName,MimeType,FileSize,PixelWidth,PixelHeight,Status,CreatedBy,ActivatedAt) VALUES(?,?,?,?,?,?,?,?,?,'Active',?,NOW())",[kind,side,Number(next.nextNo),path.basename(req.file.filename),String(req.file.originalname||'artwork').slice(0,255),actualMime,req.file.size,dimensions.width,dimensions.height,actorId(req)]);await connection.commit();const[[row]]=await db.query('SELECT * FROM BBS_Card_Master_Artwork WHERE id=?',[result.insertId]);await logAudit(req,{action:'BBS_CARD_MASTER_ARTWORK_ACTIVATE',module:'bbs',targetType:'BBS_Card_Master_Artwork',targetId:result.insertId,detail:`Activated ${kind} ${side} Master Artwork.`,metadata:{templateKind:kind,side,versionNo:Number(next.nextNo)}});return res.status(201).json({success:true,data:masterArtworkPayload(row)});}catch(error){await connection.rollback().catch(()=>{});cleanupMasterUploaded(req);return errorResponse(res,error,'master artwork upload');}finally{connection.release();}});});
router.get('/admin/card-master-artwork/:id/file',isAdmin,async(req,res)=>{try{const id=positiveInt(req.params.id);const[[row]]=await db.query('SELECT * FROM BBS_Card_Master_Artwork WHERE id=?',[id]);if(!row)return res.status(404).json({success:false,message:'Master Artwork was not found.'});const file=safeFile(masterArtworkDir,row.StoredName);if(!file||!fs.existsSync(file)||verifiedImageMime(file)!==row.MimeType)return res.status(404).json({success:false,message:'Master Artwork file is unavailable.'});res.setHeader('Content-Type',row.MimeType);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(row.OriginalName)}`);res.setHeader('Cache-Control','private, no-store');return res.sendFile(file);}catch(error){return errorResponse(res,error,'master artwork file');}});

router.get('/admin/card-designer/catalog',isAdmin,async(_req,res)=>{try{const[artwork]=await db.query("SELECT s.id ArtworkSlotID,s.SlotKey,s.ArtworkRole,s.TemplateKind,s.DepartmentID,s.SafetyUnitID,s.IsActive,s.RowVersion,v.id ArtworkVersionID,v.VersionNo,v.OriginalName,v.MimeType,v.FileSize,v.PixelWidth,v.PixelHeight,v.Status,v.CreatedAt,v.ActivatedAt,v.ArchivedAt FROM BBS_Card_Artwork_Slots s JOIN BBS_Card_Artwork_Versions v ON v.ArtworkSlotID=s.id AND v.Status='Active' WHERE s.IsActive=1 ORDER BY FIELD(s.ArtworkRole,'GlobalBack','ScopedFront'),s.TemplateKind,s.DepartmentID,s.SafetyUnitID");return res.json({success:true,data:{...catalog(),cardArtwork:artwork.map(scopedArtworkPayload),settings:{designerEnabled:(await setting('visual_card_designer_enabled'))==='1',renderingEnabled:(await setting('visual_card_designer_rendering_enabled'))==='1'}}});}catch(error){return errorResponse(res,error,'catalog');}});
router.get('/admin/card-layout-presets',isAdmin,async(req,res)=>{try{const kind=normalizeKind(req.query.kind),status=String(req.query.trash||'0')==='1'?'Trashed':'Active';const[rows]=await db.query('SELECT * FROM BBS_Card_Layout_Presets WHERE TemplateKind=? AND Status=? ORDER BY UpdatedAt DESC,id DESC',[kind,status]);return res.json({success:true,data:rows.map(presetPayload)});}catch(error){return errorResponse(res,error,'preset list');}});
router.post('/admin/card-layout-presets',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;const connection=await db.getConnection();try{const layoutVersionId=positiveInt(req.body?.layoutVersionId),presetName=String(req.body?.presetName||'').trim().slice(0,160);if(!layoutVersionId||!presetName)throw new DesignerValidationError('Draft layout and Preset name are required.');await connection.beginTransaction();const current=await detail(layoutVersionId,connection,true);if(!current){await connection.rollback();return res.status(404).json({success:false,message:'Draft layout was not found.'});}if(current.Status!=='Draft'){await connection.rollback();return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'A Preset can be saved only from a Draft layout.'});}const layout=reusablePresetLayout(current.layout),actor=actorId(req);const[result]=await connection.query("INSERT INTO BBS_Card_Layout_Presets(TemplateKind,PresetName,LayoutJSON,Status,CreatedBy,UpdatedBy) VALUES(?,?,?,'Active',?,?)",[current.TemplateKind,presetName,JSON.stringify(layout),actor,actor]);await connection.commit();await logAudit(req,{action:'BBS_CARD_LAYOUT_PRESET_CREATE',module:'bbs',targetType:'BBS_Card_Layout_Preset',targetId:result.insertId,detail:`Created ${current.TemplateKind} layout Preset.`,metadata:{layoutVersionId}});const[[row]]=await db.query('SELECT * FROM BBS_Card_Layout_Presets WHERE id=?',[result.insertId]);return res.status(201).json({success:true,data:presetPayload(row)});}catch(error){await connection.rollback().catch(()=>{});return errorResponse(res,error,'preset create');}finally{connection.release();}});
router.post('/admin/card-layout-presets/:id/apply',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;const connection=await db.getConnection();try{const presetId=positiveInt(req.params.id),layoutVersionId=positiveInt(req.body?.layoutVersionId),rowVersion=positiveInt(req.body?.rowVersion);if(!presetId||!layoutVersionId||!rowVersion)throw new DesignerValidationError('Preset, Draft layout, and RowVersion are required.');await connection.beginTransaction();const[[preset]]=await connection.query("SELECT * FROM BBS_Card_Layout_Presets WHERE id=? AND Status='Active' FOR UPDATE",[presetId]);const current=await detail(layoutVersionId,connection,true);if(!preset||!current){await connection.rollback();return res.status(404).json({success:false,message:'Preset or Draft layout was not found.'});}if(current.Status!=='Draft'){await connection.rollback();return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'A Preset can be applied only to a Draft layout.'});}if(Number(current.RowVersion)!==rowVersion){await connection.rollback();return res.status(409).json({success:false,code:'VERSION_CONFLICT',message:'Layout was changed by another user.'});}if(String(preset.TemplateKind)!==String(current.TemplateKind)){await connection.rollback();return res.status(409).json({success:false,code:'PRESET_KIND_MISMATCH',message:'Personal and Department Presets cannot be used across card types.'});}let stored;try{stored=JSON.parse(preset.LayoutJSON);}catch(_error){throw new DesignerValidationError('Preset content is invalid.');}let layout=normalizeLayoutPayload(applyPresetLayout(current.layout,stored),current.TemplateKind);layout=await canonicalizeResources(connection,current,layout);await connection.query('DELETE FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=?',[layoutVersionId]);await connection.query('DELETE FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=?',[layoutVersionId]);await connection.query('UPDATE BBS_Card_Layout_Versions SET WidthMM=?,HeightMM=?,DPI=?,DuplexFlip=?,BackRotation=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[layout.widthMM,layout.heightMM,layout.dpi,layout.duplexFlip,layout.backRotation,actorId(req),layoutVersionId]);await insertContent(connection,layoutVersionId,layout);await connection.commit();await logAudit(req,{action:'BBS_CARD_LAYOUT_PRESET_APPLY',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:layoutVersionId,detail:`Applied ${current.TemplateKind} layout Preset.`,metadata:{presetId,rowVersion}});return res.json({success:true,data:await detail(layoutVersionId)});}catch(error){await connection.rollback().catch(()=>{});return errorResponse(res,error,'preset apply');}finally{connection.release();}});
router.delete('/admin/card-layout-presets/:id',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;try{const id=positiveInt(req.params.id),rowVersion=positiveInt(req.body?.rowVersion);if(!id||!rowVersion)throw new DesignerValidationError('Preset and RowVersion are required.');const[result]=await db.query("UPDATE BBS_Card_Layout_Presets SET Status='Trashed',TrashedAt=NOW(),TrashedBy=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status='Active' AND RowVersion=?",[actorId(req),actorId(req),id,rowVersion]);if(!result.affectedRows)return res.status(409).json({success:false,code:'VERSION_CONFLICT',message:'Preset changed or is already in Trash.'});await logAudit(req,{action:'BBS_CARD_LAYOUT_PRESET_TRASH',module:'bbs',targetType:'BBS_Card_Layout_Preset',targetId:id,detail:'Moved layout Preset to recoverable Trash.'});return res.json({success:true});}catch(error){return errorResponse(res,error,'preset trash');}});
router.post('/admin/card-layout-presets/:id/restore',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;try{const id=positiveInt(req.params.id),rowVersion=positiveInt(req.body?.rowVersion);if(!id||!rowVersion)throw new DesignerValidationError('Preset and RowVersion are required.');const[result]=await db.query("UPDATE BBS_Card_Layout_Presets SET Status='Active',TrashedAt=NULL,TrashedBy=NULL,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status='Trashed' AND RowVersion=?",[actorId(req),id,rowVersion]);if(!result.affectedRows)return res.status(409).json({success:false,code:'VERSION_CONFLICT',message:'Preset changed or is no longer in Trash.'});await logAudit(req,{action:'BBS_CARD_LAYOUT_PRESET_RESTORE',module:'bbs',targetType:'BBS_Card_Layout_Preset',targetId:id,detail:'Restored layout Preset from Trash.'});return res.json({success:true});}catch(error){return errorResponse(res,error,'preset restore');}});
router.post('/admin/card-designer/runtime',isAdmin,async(req,res)=>{const connection=await db.getConnection();try{const action=String(req.body?.action||'').toLowerCase();if(!['enable','disable'].includes(action))throw new DesignerValidationError('Runtime action must be enable or disable.');await connection.beginTransaction();const[rows]=await connection.query("SELECT SettingKey,SettingValue FROM BBS_Settings WHERE SettingKey IN ('staged_admin_only','pilot_scope_only','visual_card_designer_enabled','visual_card_designer_rendering_enabled') FOR UPDATE");if(rows.length!==4)throw new DesignerValidationError('BBS Designer runtime settings are not configured.','BBS_DESIGNER_SETUP_REQUIRED');const before=runtimeSettings(rows);if(action==='enable'&&(!before.stagedAdminOnly||before.pilotScopeOnly)){const error=new DesignerValidationError('Designer runtime can be enabled only while BBS remains Admin-only.','BBS_DESIGNER_ADMIN_ONLY_REQUIRED');error.status=409;throw error;}if(before.designerEnabled!==before.renderingEnabled){const error=new DesignerValidationError('Designer runtime settings are inconsistent; disable them before enabling again.','BBS_DESIGNER_RUNTIME_STATE_CONFLICT');error.status=409;throw error;}await connection.query("UPDATE BBS_Settings SET SettingValue=?,UpdatedAt=NOW(),UpdatedBy=? WHERE SettingKey IN ('visual_card_designer_enabled','visual_card_designer_rendering_enabled')",[action==='enable'?'1':'0',actorId(req)]);const[afterRows]=await connection.query("SELECT SettingKey,SettingValue FROM BBS_Settings WHERE SettingKey IN ('staged_admin_only','pilot_scope_only','visual_card_designer_enabled','visual_card_designer_rendering_enabled') ORDER BY SettingKey");const settings=runtimeSettings(afterRows);if(settings.designerEnabled!==settings.renderingEnabled||(action==='enable'&&(!settings.stagedAdminOnly||settings.pilotScopeOnly)))throw new Error('Designer runtime setting verification failed.');await connection.commit();await logAudit(req,{action:action==='enable'?'BBS_CARD_DESIGNER_RUNTIME_ENABLE':'BBS_CARD_DESIGNER_RUNTIME_DISABLE',module:'bbs',targetType:'BBS_Settings',targetId:'visual_card_designer_runtime',detail:`${action} Visual Card Designer runtime while staged Admin-only.`,metadata:settings});return res.json({success:true,data:{...settings,action}});}catch(error){await connection.rollback().catch(()=>{});if(error?.status===409)return res.status(409).json({success:false,code:error.code,message:error.message});return errorResponse(res,error,'runtime setting');}finally{connection.release();}});
router.get('/admin/card-designer/:kind/:templateId/versions',isAdmin,async(req,res)=>{try{const info=kindInfo(req.params.kind),templateId=positiveInt(req.params.templateId),deleted=String(req.query.trash||'0')==='1'?1:0;if(!templateId)throw new DesignerValidationError('Template ID is required.');const[rows]=await db.query(`SELECT id,TemplateKind,VersionNo,WidthMM,HeightMM,DPI,DuplexFlip,BackRotation,Status,BootstrapSource,RowVersion,IsDeleted,CreatedAt,UpdatedAt,ActivatedAt,ArchivedAt,DeletedAt FROM BBS_Card_Layout_Versions WHERE ${info.parentColumn}=? AND IsDeleted=? ORDER BY VersionNo DESC,id DESC`,[templateId,deleted]);return res.json({success:true,data:rows});}catch(error){return errorResponse(res,error,'version list');}});
router.post('/admin/card-designer/:kind/:templateId/versions',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;const connection=await db.getConnection(),createdFiles=[];try{const info=kindInfo(req.params.kind),templateId=positiveInt(req.params.templateId),sourceVersionId=positiveInt(req.body?.sourceVersionId);if(!templateId)throw new DesignerValidationError('Template ID is required.');await connection.beginTransaction();const[[parent]]=await connection.query(`SELECT * FROM ${info.parentTable} WHERE id=? FOR UPDATE`,[templateId]);if(!parent){await connection.rollback();return res.status(404).json({success:false,message:'Parent template was not found.'});}const[[nextRow]]=await connection.query(`SELECT COALESCE(MAX(VersionNo),0)+1 nextNo FROM BBS_Card_Layout_Versions WHERE ${info.parentColumn}=?`,[templateId]);let payload;if(sourceVersionId){const source=await detail(sourceVersionId,connection,true);if(!source||source.TemplateKind!==info.kind||Number(source[info.parentColumn])!==templateId){await connection.rollback();return res.status(404).json({success:false,message:'Source layout version was not found for this template.'});}if(source.layout.elements.some(element=>element.assetId)){throw new DesignerValidationError('Layouts with static private assets must be recreated and re-uploaded for each Draft.','PRIVATE_ASSET_CLONE_FORBIDDEN');}payload=source.layout;}else payload=legacyLayout(parent,info.kind);let layout=normalizeLayoutPayload(payload,info.kind);const actor=actorId(req);const[result]=await connection.query("INSERT INTO BBS_Card_Layout_Versions(TemplateKind,PersonalTemplateID,DepartmentTemplateID,VersionNo,WidthMM,HeightMM,DPI,DuplexFlip,BackRotation,Status,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,'Draft',?,?)",[info.kind,info.kind==='Personal'?templateId:null,info.kind==='Department'?templateId:null,Number(nextRow.nextNo),layout.widthMM,layout.heightMM,layout.dpi,layout.duplexFlip,layout.backRotation,actor,actor]);layout=await masterArtworkSnapshot(connection,result.insertId,info.kind,layout,actor,createdFiles);await insertContent(connection,result.insertId,layout);await connection.commit();await logAudit(req,{action:'BBS_CARD_LAYOUT_DRAFT_CREATE',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:result.insertId,detail:'Created Draft visual card layout with logical ScopedFront and GlobalBack Artwork bindings.',metadata:{templateKind:info.kind,templateId,sourceVersionId:sourceVersionId||null,artworkRoles:layout.sides.map(side=>side.artworkRole)}});return res.status(201).json({success:true,data:await detail(result.insertId)});}catch(error){await connection.rollback().catch(()=>{});for(const file of createdFiles)if(file&&fs.existsSync(file))fs.unlinkSync(file);return errorResponse(res,error,'create draft');}finally{connection.release();}});
router.get('/admin/card-designer/versions/:id',isAdmin,async(req,res)=>{try{const row=await detail(positiveInt(req.params.id));if(!row)return res.status(404).json({success:false,message:'Layout version was not found.'});return res.json({success:true,data:row});}catch(error){return errorResponse(res,error,'version detail');}});
router.put('/admin/card-designer/versions/:id',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;const connection=await db.getConnection();try{const id=positiveInt(req.params.id),rowVersion=positiveInt(req.body?.rowVersion);if(!id||!rowVersion)throw new DesignerValidationError('Layout version ID and RowVersion are required.');await connection.beginTransaction();const current=await detail(id,connection,true);if(!current){await connection.rollback();return res.status(404).json({success:false,message:'Layout version was not found.'});}if(current.Status!=='Draft'){await connection.rollback();return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'Only a Draft layout can be edited.'});}if(Number(current.RowVersion)!==rowVersion){await connection.rollback();return res.status(409).json({success:false,code:'VERSION_CONFLICT',message:'Layout was changed by another user.'});}let layout=normalizeLayoutPayload(req.body?.layout,current.TemplateKind);layout=await canonicalizeResources(connection,current,layout);await connection.query('DELETE FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=?',[id]);await connection.query('DELETE FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=?',[id]);await connection.query('UPDATE BBS_Card_Layout_Versions SET WidthMM=?,HeightMM=?,DPI=?,DuplexFlip=?,BackRotation=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[layout.widthMM,layout.heightMM,layout.dpi,layout.duplexFlip,layout.backRotation,actorId(req),id]);await insertContent(connection,id,layout);await connection.commit();await logAudit(req,{action:'BBS_CARD_LAYOUT_DRAFT_UPDATE',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:id,detail:'Updated Draft visual card layout.',metadata:{rowVersion}});return res.json({success:true,data:await detail(id)});}catch(error){await connection.rollback().catch(()=>{});return errorResponse(res,error,'update draft');}finally{connection.release();}});
router.post('/admin/card-designer/versions/:id/master-artwork-rebase',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;const connection=await db.getConnection(),createdFiles=[];try{const id=positiveInt(req.params.id),rowVersion=positiveInt(req.body?.rowVersion);if(!id||!rowVersion)throw new DesignerValidationError('Draft layout and RowVersion are required.');await connection.beginTransaction();const current=await detail(id,connection,true);if(!current){await connection.rollback();return res.status(404).json({success:false,message:'Layout version was not found.'});}if(current.Status!=='Draft'){await connection.rollback();return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'Only a Draft layout can rebase Card Artwork bindings.'});}if(Number(current.RowVersion)!==rowVersion){await connection.rollback();return res.status(409).json({success:false,code:'VERSION_CONFLICT',message:'Layout was changed by another user.'});}let layout=normalizeLayoutPayload(req.body?.layout||current.layout,current.TemplateKind);const sides=new Set(layout.sides.map(side=>side.side));if(!sides.has('Front')||!sides.has('Back'))throw new DesignerValidationError('Front and Back sides are required to repair Card Artwork bindings.','MASTER_ARTWORK_REQUIRED');await validateElementAssets(connection,id,layout);layout=await masterArtworkSnapshot(connection,id,current.TemplateKind,layout,actorId(req),createdFiles);await connection.query('DELETE FROM BBS_Card_Layout_Elements WHERE LayoutVersionID=?',[id]);await connection.query('DELETE FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=?',[id]);await connection.query('UPDATE BBS_Card_Layout_Versions SET WidthMM=?,HeightMM=?,DPI=?,DuplexFlip=?,BackRotation=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[layout.widthMM,layout.heightMM,layout.dpi,layout.duplexFlip,layout.backRotation,actorId(req),id]);await insertContent(connection,id,layout);await connection.commit();await logAudit(req,{action:'BBS_CARD_LAYOUT_MASTER_ARTWORK_REBASE',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:id,detail:'Repaired Draft backgrounds to logical ScopedFront and GlobalBack Artwork bindings while preserving layout content.',metadata:{rowVersion,artworkRoles:layout.sides.map(side=>side.artworkRole)}});return res.json({success:true,data:await detail(id)});}catch(error){await connection.rollback().catch(()=>{});for(const file of createdFiles)if(file&&fs.existsSync(file))fs.unlinkSync(file);return errorResponse(res,error,'Card Artwork binding repair');}finally{connection.release();}});
router.post('/admin/card-designer/versions/:id/lifecycle',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;const connection=await db.getConnection();try{const id=positiveInt(req.params.id),action=String(req.body?.action||'').toLowerCase();if(!id||!['activate','archive'].includes(action))throw new DesignerValidationError('Lifecycle action must be activate or archive.');await connection.beginTransaction();const current=await detail(id,connection,true);if(!current){await connection.rollback();return res.status(404).json({success:false,message:'Layout version was not found.'});}const info=kindInfo(current.TemplateKind);if(action==='activate'){if(current.Status!=='Draft'){await connection.rollback();return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'Only a Draft layout can be activated.'});}if(current.readiness.status==='Blocked'){await connection.rollback();return res.status(409).json({success:false,code:'LAYOUT_NOT_READY',message:'A blocked layout cannot be activated.'});}await connection.query(`UPDATE BBS_Card_Layout_Versions SET Status='Archived',ArchivedAt=NOW(),ArchivedBy=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE ${info.parentColumn}=? AND Status='Active'`,[actorId(req),actorId(req),current[info.parentColumn]]);await connection.query("UPDATE BBS_Card_Layout_Versions SET Status='Active',ActivatedAt=NOW(),ActivatedBy=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?",[actorId(req),actorId(req),id]);}else{if(current.Status!=='Draft'){await connection.rollback();return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'Only a Draft layout can be archived.'});}await connection.query("UPDATE BBS_Card_Layout_Versions SET Status='Archived',ArchivedAt=NOW(),ArchivedBy=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?",[actorId(req),actorId(req),id]);}await connection.commit();await logAudit(req,{action:action==='activate'?'BBS_CARD_LAYOUT_ACTIVATE':'BBS_CARD_LAYOUT_ARCHIVE',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:id,detail:`${action} visual card layout.`});return res.json({success:true,data:await detail(id)});}catch(error){await connection.rollback().catch(()=>{});return errorResponse(res,error,'layout lifecycle');}finally{connection.release();}});
router.post('/admin/card-designer/versions/:id/readiness',isAdmin,async(req,res)=>{try{const row=await detail(positiveInt(req.params.id));if(!row)return res.status(404).json({success:false,message:'Layout version was not found.'});return res.json({success:true,data:row.readiness});}catch(error){return errorResponse(res,error,'readiness');}});
router.post('/admin/card-designer/versions/:id/assets',isAdmin,(req,res)=>{assetUpload.single('asset')(req,res,async uploadError=>{if(uploadError)return res.status(400).json({success:false,message:uploadError.code==='LIMIT_FILE_SIZE'?'Designer image must not exceed 10 MB.':'Designer image upload failed.'});if(!await requireEnabled(res)){cleanupUploaded(req);return;}try{const id=positiveInt(req.params.id),assetKey=String(req.body?.assetKey||'').trim().slice(0,80);if(!req.file||!id||!/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(assetKey)){cleanupUploaded(req);return res.status(400).json({success:false,message:'A valid asset key and JPG, PNG, or WebP image are required.'});}const actualMime=verifiedImageMime(req.file.path);if(!actualMime||actualMime!==req.file.mimetype){cleanupUploaded(req);return res.status(400).json({success:false,message:'Designer image content does not match its file type.'});}const connection=await db.getConnection();try{await connection.beginTransaction();const current=await detail(id,connection,true);if(!current){await connection.rollback();cleanupUploaded(req);return res.status(404).json({success:false,message:'Layout version was not found.'});}if(current.Status!=='Draft'){await connection.rollback();cleanupUploaded(req);return res.status(409).json({success:false,code:'IMMUTABLE_LAYOUT_VERSION',message:'Assets can be uploaded only to a Draft layout.'});}const[result]=await connection.query("INSERT INTO BBS_Card_Layout_Assets(LayoutVersionID,AssetKey,StoredName,OriginalName,MimeType,FileSize,Status,CreatedBy) VALUES(?,?,?,?,?,?,'Active',?)",[id,assetKey,path.basename(req.file.filename),String(req.file.originalname||'image').slice(0,255),actualMime,req.file.size,actorId(req)]);await connection.commit();const[[row]]=await db.query('SELECT * FROM BBS_Card_Layout_Assets WHERE id=?',[result.insertId]);await logAudit(req,{action:'BBS_CARD_LAYOUT_ASSET_UPLOAD',module:'bbs',targetType:'BBS_Card_Layout_Asset',targetId:result.insertId,detail:`layout=${id}; key=${assetKey}`});return res.status(201).json({success:true,data:assetPayload(row)});}catch(error){await connection.rollback().catch(()=>{});cleanupUploaded(req);return errorResponse(res,error,'asset upload');}finally{connection.release();}}catch(error){cleanupUploaded(req);return errorResponse(res,error,'asset upload');}});});
router.get('/admin/card-designer/assets/:assetId/file',isAdmin,async(req,res)=>{try{const assetId=positiveInt(req.params.assetId);const[[row]]=await db.query("SELECT * FROM BBS_Card_Layout_Assets WHERE id=? AND Status='Active'",[assetId]);if(!row)return res.status(404).json({success:false,message:'Designer asset was not found.'});const file=safeFile(assetDir,row.StoredName);if(!file||!fs.existsSync(file)||verifiedImageMime(file)!==row.MimeType)return res.status(404).json({success:false,message:'Designer asset file is unavailable.'});res.setHeader('Content-Type',row.MimeType);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(row.OriginalName)}`);res.setHeader('Cache-Control','private, no-store');return res.sendFile(file);}catch(error){return errorResponse(res,error,'asset file');}});
router.get('/admin/card-designer/versions/:id/sides/:side/background',isAdmin,async(req,res)=>{try{const id=positiveInt(req.params.id),side=String(req.params.side||'').toLowerCase()==='back'?'Back':'Front';const record=await detail(id);if(!record)return res.status(404).json({success:false,message:'Layout version was not found.'});const row=record.layout.sides.find(item=>item.side===side);if(!row)return res.status(404).json({success:false,message:'Layout background was not found.'});let root,file,mime=row.backgroundMimeType,name=row.backgroundOriginalName;if(row.storageClass==='CardArtwork'){if(!row.artworkVersionId)return res.status(409).json({success:false,code:'CARD_ARTWORK_REQUIRED',message:`Current ${row.artworkRole||side} Card Artwork is not configured.`});const[[artwork]]=await db.query('SELECT StoredName,OriginalName,MimeType FROM BBS_Card_Artwork_Versions WHERE id=?',[row.artworkVersionId]);if(!artwork)return res.status(404).json({success:false,message:'Resolved Card Artwork version was not found.'});root=masterArtworkDir;file=safeFile(root,artwork.StoredName);mime=artwork.MimeType;name=artwork.OriginalName;}else{if(!['PersonalTemplate','DepartmentTemplate','DesignerAsset'].includes(row.storageClass))return res.status(404).json({success:false,message:'Layout background was not found.'});root=row.storageClass==='DesignerAsset'?assetDir:templateDir;const[[stored]]=await db.query('SELECT BackgroundStoredName FROM BBS_Card_Layout_Sides WHERE LayoutVersionID=? AND Side=?',[id,side]);file=safeFile(root,stored?.BackgroundStoredName);}if(!file||!fs.existsSync(file)||verifiedImageMime(file)!==mime)return res.status(404).json({success:false,message:'Layout background file is unavailable.'});res.setHeader('Content-Type',mime);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(name)}`);res.setHeader('Cache-Control','private, no-store');return res.sendFile(file);}catch(error){return errorResponse(res,error,'side background');}});

router.delete('/admin/card-designer/versions/:id',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;try{const id=positiveInt(req.params.id),rowVersion=positiveInt(req.body?.rowVersion);if(!id||!rowVersion)throw new DesignerValidationError('Draft layout and RowVersion are required.');const[result]=await db.query("UPDATE BBS_Card_Layout_Versions SET IsDeleted=1,DeletedAt=NOW(),DeletedBy=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status='Draft' AND IsDeleted=0 AND RowVersion=?",[actorId(req),actorId(req),id,rowVersion]);if(!result.affectedRows)return res.status(409).json({success:false,code:'SAFE_TRASH_REJECTED',message:'Only an unchanged Draft layout can be moved to Trash.'});await logAudit(req,{action:'BBS_CARD_LAYOUT_TRASH',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:id,detail:'Moved Draft layout to recoverable Trash; assets and history were retained.'});return res.json({success:true});}catch(error){return errorResponse(res,error,'layout trash');}});
router.post('/admin/card-designer/versions/:id/restore',isAdmin,async(req,res)=>{if(!await requireEnabled(res))return;try{const id=positiveInt(req.params.id),rowVersion=positiveInt(req.body?.rowVersion);if(!id||!rowVersion)throw new DesignerValidationError('Draft layout and RowVersion are required.');const[result]=await db.query("UPDATE BBS_Card_Layout_Versions SET IsDeleted=0,DeletedAt=NULL,DeletedBy=NULL,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status='Draft' AND IsDeleted=1 AND RowVersion=?",[actorId(req),id,rowVersion]);if(!result.affectedRows)return res.status(409).json({success:false,code:'VERSION_CONFLICT',message:'Draft layout changed or is no longer in Trash.'});await logAudit(req,{action:'BBS_CARD_LAYOUT_RESTORE',module:'bbs',targetType:'BBS_Card_Layout_Version',targetId:id,detail:'Restored Draft layout from Trash.'});return res.json({success:true,data:await detail(id)});}catch(error){return errorResponse(res,error,'layout restore');}});

module.exports=router;
